import "core-js/modules/web.dom.iterable";
import "core-js/modules/es6.array.find";
import { ippoolSearch, initIpPool as _initIpPool, setIpLevel, setNewGateway } from "@/api/operation/safeaccess/subnet";
import { setIsUsed } from "@/api/operation/safeaccess/newIpPool";
import { getDictList as _getDictList } from "@/api/dict";
export default {
  props: ['isShow', 'arrtId', 'institutionName'],
  data: function data() {
    return {
      levelList: [],
      isUsedList: [],
      searchForm: {
        current: 1,
        size: 10
      },
      rules: {
        name: [{
          required: true,
          message: '名称不能为空',
          trigger: 'blur'
        }]
      },
      saveLoading: false,
      tableData: [],
      dataList: [],
      selectionList: [],
      total: 0,
      tableLoading: false,
      //表格加载
      tableHeight: undefined
    };
  },
  computed: {
    // ids() {
    //   let ids = [];
    //   this.selectionList.forEach(ele => {
    //     ids.push(ele.id);
    //   });
    //   return ids.join(",");
    // },
  },
  created: function created() {
    this.getList();
    //加载字典--工单状态
    this.getDictList("itump_ippool_level");
    this.getDictList("itump_ippool_isUse");
  },
  methods: {
    selectionChange: function selectionChange(val) {
      this.selectionList = val;
    },
    ipLevelFormatter: function ipLevelFormatter(row) {
      if (row.ipLevel === '1') {
        return '普通地址';
      } else if (row.ipLevel === '2') {
        return '预留地址';
      } else {
        return '禁用地址';
      }
    },
    isUsedFormatter: function isUsedFormatter(row) {
      if (row.isUsed === '0') {
        return '未分配';
      } else if (row.isUsed === '1') {
        return '已分配';
      } else {
        return '网关';
      }
    },
    handleSubmit: function handleSubmit() {
      this.$emit('setVal', this.searchForm);
    },
    handleCancel: function handleCancel() {
      this.$emit('close');
    },
    getDictList: function getDictList(code) {
      var _this = this;
      //加载字典
      _getDictList(code).then(function (res) {
        if (code === 'itump_ippool_level') {
          // 工单状态
          _this.levelList = res.data;
        } else if (code === 'itump_ippool_isUse') {
          _this.isUsedList = res.data;
        }
      });
    },
    // 查询
    handleQuery: function handleQuery() {
      this.searchForm.current = 1;
      this.getList();
    },
    // 重置
    searchReset: function searchReset() {
      this.searchForm = {
        current: 1,
        size: 20
      };
      this.getList();
    },
    //初始化IP地址池
    initIpPool: function initIpPool() {
      var _this2 = this;
      var params = {
        subnetId: this.arrtId
      };
      this.tableLoading = true;
      _initIpPool(params).then(function (resp) {
        if (resp) {
          _this2.$message({
            message: "ip地址池初始化成功",
            type: "success"
          });
          _this2.getList();
        } else {
          _this2.$message({
            message: "ip地址池初始化失败，请重试",
            type: "error"
          });
        }
        _this2.tableLoading = false;
      }).catch(function () {
        _this2.$message.error('初始化IP地址池出现异常');
        _this2.tableLoading = false;
      });
    },
    updateLevel: function updateLevel(val) {
      var _this3 = this;
      if (this.selectionList.length != 0) {
        for (var i = 0; i < this.selectionList.length; i++) {
          if (this.selectionList[i].isUsed != '0') {
            this.$message({
              message: "只能修改未分配地址",
              type: "warning"
            });
            return;
          }
        }
        // console.log(123, this.selectionList)

        var params = {
          ids: this.selectionList.map(function (el) {
            return el.ipId;
          }),
          ipLevel: val
        };
        setIpLevel(params).then(function (rel) {
          if (rel.code != 200) return;
          _this3.$message.success("设置成功");
          _this3.getList();
        });
      } else {
        this.$message.warning('请选择一条数据');
        return;
      }
    },
    updateNewGateway: function updateNewGateway() {
      var _this4 = this;
      if (this.selectionList.length != 1) {
        this.$message.warning('只能选择一个网关地址');
        return;
      }
      if (this.selectionList[0].isUsed != '0') {
        this.$message.warning('所选地址已分配，只能选择未分配的地址设置为新网关');
        return;
      }
      var oldParams = null;
      var fItem = this.tableData.find(function (a) {
        return a.isUsed == '2';
      });
      if (fItem) {
        oldParams = {
          ipId: fItem.ipId,
          isUsed: 0
        };
      }
      var params = {
        ipId: this.selectionList[0].ipId
        // subnet: this.selectionList[0].subnet
      };
      setNewGateway(params).then(function (rel) {
        if (rel.code != 200) return;
        _this4.$message({
          message: "设置为网关成功",
          type: "success"
        });
        if (oldParams) {
          //将旧网关设置成未分配状态
          setIsUsed(oldParams).then(function (res) {
            _this4.getList();
          });
        }
      });
    },
    // 查询
    getList: function getList() {
      var _this5 = this;
      this.searchForm.subnet = this.arrtId;
      this.tableLoading = true;
      ippoolSearch(this.searchForm).then(function (res) {
        // console.log(123, res)
        res.data.records.forEach(function (ele) {
          ele.orgName = _this5.institutionName;
        });
        _this5.tableData = res.data.records;
        _this5.total = res.data.total;
        _this5.tableLoading = false;
      }).catch(function () {
        _this5.tableLoading = false;
      });
    }
  }
};
